import {clamp,decode,encode} from './engine.js';
export const effectKeys=['cameraExposure','cameraTemperature','cameraTint','meterEV','sceneHighlights','sceneShadows','headroom','lensBlur','diffusion','halationRadius','grainSize','grainChroma','glare','sharpen','contrastMaskHighlights','contrastMaskShadows','postTint','curveShadows','curveMid','curveHighlights','balanceR','balanceG','balanceB','shadowR','shadowG','shadowB','highlightR','highlightG','highlightB','filmLongMm','antihalationRemoved'];
export function blackbody(kelvin){const t=kelvin/100,r=t<=66?255:329.698727446*(t-60)**-.1332047592,g=t<=66?99.4708025861*Math.log(t)-161.1195681661:288.1221695283*(t-60)**-.0755148492,b=t>=66?255:t<=19?0:138.5177312231*Math.log(t-10)-305.0447927307;return [r,g,b].map(v=>clamp(v/255,.025,1));}
export function cameraGains(p){const bb=blackbody(p.cameraTemperature||5500),ref=blackbody(5500),g=ref.map((v,k)=>v/bb[k]);g[1]*=2**(-(p.cameraTint||0)/150);return g;}
export function sceneMap(rgb,p){const y=Math.max(1e-8,rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722),ev=Math.log2(y/.184);let mapped=ev;if(ev>2&&p.sceneHighlights>0){const d=ev-2;mapped=2+d/(1+p.sceneHighlights*d*.3);}if(ev< -2&&p.sceneShadows>0){const d=-2-ev;mapped=-2-d/(1+p.sceneShadows*d*.3);}return rgb.map(v=>v*2**(mapped-ev));}
export function preEffects(encoded,p){const gains=cameraGains(p),g=2**((p.cameraExposure||0)+(p.meterEV||0));let lin=encoded.map((v,k)=>decode(v)*g*gains[k]);if(p.headroom>0){const m=Math.max(...lin),h=clamp((m-.65)/.35);lin=lin.map(v=>v*2**(p.headroom*h*h*.6));}return sceneMap(lin,p);}
export function postEffects(rgb,p){let v=rgb.map((v,k)=>encode(decode(Math.max(0,v))*2**p.exposure*(k===0?1+p.temperature*.002:k===2?1-p.temperature*.002:2**(-(p.postTint||0)/150))));v=v.map(x=>(x-.5)*(1+p.contrast/100)+.5);let y=v[0]*.2126+v[1]*.7152+v[2]*.0722;v=v.map(x=>y+(x-y)*(1+p.saturation/100));const bend=x=>{const w=4*x*(1-x);return x+w*((p.curveShadows||0)*Math.exp(-(((x-.2)/.18)**2))+(p.curveMid||0)*Math.exp(-(((x-.5)/.2)**2))+(p.curveHighlights||0)*Math.exp(-(((x-.8)/.18)**2)))*.004;};v=v.map(bend);y=clamp(v[0]*.2126+v[1]*.7152+v[2]*.0722);const low=(1-y)**2,high=y*y;v=v.map((x,k)=>x+((p[['balanceR','balanceG','balanceB'][k]]||0)+(p[['shadowR','shadowG','shadowB'][k]]||0)*low+(p[['highlightR','highlightG','highlightB'][k]]||0)*high)*.003);if(p.printEffects!==false&&p.glare>0)v=v.map(x=>x+(1-x)*p.glare/100*.035);return v.map(x=>clamp(x));}
export function curvePreview(p,x){return clamp(x+4*x*(1-x)*((p.curveShadows||0)*Math.exp(-(((x-.2)/.18)**2))+(p.curveMid||0)*Math.exp(-(((x-.5)/.2)**2))+(p.curveHighlights||0)*Math.exp(-(((x-.8)/.18)**2)))*.004);}
